import { useEffect } from 'react';

import { useApi, useUser } from '@proton/components/hooks';
import { queryUserActivePing } from '@proton/shared/lib/api/drive/user';
import localStorageWithExpiry from '@proton/shared/lib/api/helpers/localStorageWithExpiry';
import { ACTIVE_PING_INTERVAL } from '@proton/shared/lib/drive/constants';

/*
    This hook is about pinging the api to tell that a user is active.
    The ping is sent maximum every 6 hours, regardless if the web app has been opened or closed during that time period.
    The ping can only be sent if the document is active, visible and in the foreground.

    Scenario 1:
        - Customer open the web app at T+0 -> active ping is sent 
        - Customer closes the web app
        - Customer open the web app T+5HOURS -> active is not sent since last ping was sent less than 6 hours ago
        - Customer leaves the tab open in the foreground (active) at T+6HOURS -> active ping is sent

    Scenario 2:
        - Customer open the web app at T+0 -> active ping is sent
        - Customer leaves the tab open in the background (not active) at T+6HOURS -> active ping is not sent since customer web app is in the background 
        - Customers comes back to the web app (active) at T+8HOURS -> active ping is sent

    Scenario 3:
        - Customer open the web app at T+0 -> active ping is sent
        - Customer leaves the tab open in the foreground (active) at T+6HOURS -> active ping is sent
*/

// We have business logic relying on this constant, please change with caution!
export const LAST_ACTIVE_PING = 'drive-last-active';

export const useActivePing = (interval: number = ACTIVE_PING_INTERVAL) => {
    const api = useApi();
    const [user] = useUser();
    // We have business logic relying on this key, please change with caution!
    const key = `${LAST_ACTIVE_PING}-${user.ID}`;

    const shouldSendActivePing = () => {
        const lastActivePing = localStorageWithExpiry.getData(key);
        return (
            document.visibilityState === 'visible' &&
            (!lastActivePing || Date.now() - Number(lastActivePing) > interval)
        );
    };

    const sendActivePingIfVisible = () => {
        if (shouldSendActivePing()) {
            void api(queryUserActivePing());
            localStorageWithExpiry.storeData(key, Date.now().toString(), interval);
        }
    };

    const cleanLocalStorage = () => {
        Object.keys(localStorage).forEach((k) => {
            if (k.startsWith(LAST_ACTIVE_PING) && k !== key) {
                localStorageWithExpiry.deleteDataIfExpired(k);
            }
        });
    };

    const handleBeforeUnload = () => {
        localStorageWithExpiry.storeData(key, Date.now().toString(), interval);
    };

    useEffect(() => {
        cleanLocalStorage();

        sendActivePingIfVisible();

        const handleVisibilityChange = () => {
            sendActivePingIfVisible();
        };

        document.addEventListener('visibilitychange', handleVisibilityChange);
        window.addEventListener('beforeunload', handleBeforeUnload);

        const intervalFunction = setInterval(() => {
            sendActivePingIfVisible();
        }, interval);

        return () => {
            document.removeEventListener('visibilitychange', handleVisibilityChange);
            window.removeEventListener('beforeunload', handleBeforeUnload);
            clearInterval(intervalFunction);
        };
    }, [api, interval]);
};
import { renderHook } from '@testing-library/react-hooks';

import { ACTIVE_PING_INTERVAL } from '@proton/shared/lib/drive/constants';

import { LAST_ACTIVE_PING, useActivePing } from './useActivePing';

const mockedApi = jest.fn();
const mockedUser = { ID: 123 };

jest.mock('@proton/components/hooks', () => ({
    useApi: () => jest.fn().mockImplementation(mockedApi.mockResolvedValue('')),
    useUser: () => [mockedUser],
}));

describe('useActivePing', () => {
    beforeAll(() => {
        jest.useFakeTimers();
    });

    afterEach(() => {
        jest.clearAllMocks();
        jest.clearAllTimers();
        window.localStorage.clear();
    });

    afterAll(() => {
        jest.useRealTimers();
    });

    it('call the api immediately', async () => {
        renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('call the api periodically based on the interval', async () => {
        const interval = 1000;
        const { waitFor } = renderHook(() => useActivePing(interval));

        jest.advanceTimersByTime(interval);

        await waitFor(() => expect(mockedApi).toHaveBeenCalledTimes(2));
    });

    it('does not call api if interval time has not passed since last ping', () => {
        const interval = 10000;

        const { rerender } = renderHook(() => useActivePing(interval));

        jest.advanceTimersByTime(interval / 2);

        rerender();

        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('call api again if interval has passed since last ping', () => {
        const interval = 10000;

        const { rerender } = renderHook(() => useActivePing(interval));
        jest.advanceTimersByTime(interval / 2);
        rerender(interval);

        expect(mockedApi).toHaveBeenCalledTimes(1);

        jest.advanceTimersByTime(interval / 2);
        rerender(interval);

        expect(mockedApi).toHaveBeenCalledTimes(2);
    });

    it('call api only when document.visibilityState === visible', () => {
        Object.defineProperty(document, 'visibilityState', { value: 'hidden', writable: true });
        renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(0);
    });

    it("call api when document.visibilityState === visible and you're passed the interval time", () => {
        Object.defineProperty(document, 'visibilityState', { value: 'hidden', writable: true });
        renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(0);

        Object.defineProperty(document, 'visibilityState', { value: 'visible', writable: true });
        document.dispatchEvent(new Event('visibilitychange'));
        expect(mockedApi).toHaveBeenCalledTimes(1);
    });

    it('remove previously stored LAST_ACTIVE_PING value if user changes and data is expired', () => {
        const { rerender } = renderHook(() => useActivePing());
        expect(mockedApi).toHaveBeenCalledTimes(1);
        expect(Object.keys(localStorage).filter((k) => k.startsWith(LAST_ACTIVE_PING)).length).toEqual(1);
        // change user ID
        mockedUser.ID = 456;
        // Expired
        const originalDateNow = Date.now();
        Date.now = jest.fn(() => originalDateNow + ACTIVE_PING_INTERVAL + 1);
        rerender();
        expect(Object.keys(localStorage).filter((k) => k.startsWith(LAST_ACTIVE_PING)).length).toEqual(1);
    });
});

import type { PersistedSession } from '@proton/shared/lib/authentication/SessionInterface';
import { STORAGE_PREFIX } from '@proton/shared/lib/authentication/persistedSessionStorage';

import { LAST_ACTIVE_PING } from '../store/_user/useActivePing';
import { sendErrorReport } from './errorHandling';
import { EnrichedError } from './errorHandling/EnrichedError';

const getLastActiveUserId = () => {
    const storageKeys = Object.keys(localStorage);
    let lastActiveUserId = '';
    let lastAccess = 0;

    for (const k of storageKeys) {
        if (k.startsWith(LAST_ACTIVE_PING)) {
            const data = JSON.parse(localStorage[k]);
            const lastPing = Number(data.value);
            if (lastAccess < lastPing) {
                lastAccess = lastPing;
                lastActiveUserId = k.substring(k.indexOf(LAST_ACTIVE_PING) + LAST_ACTIVE_PING.length + 1);
            }
        }
    }
    return lastActiveUserId || null;
};

export const getLastPersistedLocalID = () => {
    try {
        const storageKeys = Object.keys(localStorage);
        // Get localID from last active session
        // This support multi tabs and multi accounts
        const lastActiveUserId = getLastActiveUserId();
        if (lastActiveUserId) {
            for (const k of storageKeys) {
                if (k.startsWith(STORAGE_PREFIX)) {
                    const data = JSON.parse(localStorage[k]);
                    if (data.UserID === lastActiveUserId && data.UID) {
                        return Number(k.substring(STORAGE_PREFIX.length));
                    }
                }
            }
        }

        // Fallback: rely on last storage prefix
        // This does not support multi tabs
        let lastLocalID: { ID: number; persistedAt: number } | null = null;
        for (const k of storageKeys) {
            if (k.startsWith(STORAGE_PREFIX)) {
                const data = JSON.parse(localStorage[k]) as { persistedAt: number };
                if (lastLocalID === null || data.persistedAt > lastLocalID.persistedAt) {
                    lastLocalID = {
                        persistedAt: data.persistedAt,
                        ID: Number(k.substring(STORAGE_PREFIX.length)),
                    };
                }
            }
        }

        return lastLocalID?.ID || null;
    } catch (e) {
        sendErrorReport(
            new EnrichedError('Failed to parse JSON from localStorage', {
                extra: {
                    e,
                },
            })
        );
        return null;
    }
};

export const getLastActivePersistedUserSessionUID = (): string | null => {
    try {
        // Last Active Persisted Session in Drive apps
        const storageKeys = Object.keys(localStorage);
        const lastActiveUserId = getLastActiveUserId();
        if (lastActiveUserId) {
            for (const k of storageKeys) {
                if (k.startsWith(STORAGE_PREFIX)) {
                    const data = JSON.parse(localStorage[k]);
                    if (data.UserID === lastActiveUserId && data.UID) {
                        return data.UID;
                    }
                }
            }
        }

        // Last Active Persisted Session in any apps
        let persistedSession: PersistedSession | null = null;
        for (const k of storageKeys) {
            if (k.startsWith(STORAGE_PREFIX)) {
                const data = JSON.parse(localStorage[k]) as PersistedSession;
                if (persistedSession === null || data.persistedAt > persistedSession.persistedAt) {
                    persistedSession = data;
                }
            }
        }

        return persistedSession?.UID ?? null;
    } catch (e) {
        sendErrorReport(
            new EnrichedError('Failed to parse JSON from localStorage', {
                extra: {
                    e,
                },
            })
        );
        return null;
    }
};
import { createContext, useContext, useRef, useState } from 'react';

import { useApi, useAuthentication } from '@proton/components';
import metrics from '@proton/metrics';
import { queryInitSRPHandshake, queryShareURLAuth } from '@proton/shared/lib/api/drive/sharing';
import { getApiError } from '@proton/shared/lib/api/helpers/apiErrorHelper';
import { resumeSession } from '@proton/shared/lib/authentication/persistedSessionHelper';
import { HTTP_ERROR_CODES } from '@proton/shared/lib/errors';
import { getUIDHeaders, withAuthHeaders } from '@proton/shared/lib/fetch/headers';
import type { UserModel } from '@proton/shared/lib/interfaces';
import type { SRPHandshakeInfo } from '@proton/shared/lib/interfaces/drive/sharing';
import { srpAuth } from '@proton/shared/lib/srp';
import { formatUser } from '@proton/shared/lib/user/helpers';

import {
    getLastActivePersistedUserSessionUID,
    getLastPersistedLocalID,
} from '../../utils/lastActivePersistedUserSession';
import retryOnError from '../../utils/retryOnError';
import { hasCustomPassword, hasGeneratedPasswordIncluded, isLegacySharedUrl } from '../_shares';
import useDebouncedRequest from './useDebouncedRequest';

export const ERROR_CODE_INVALID_SRP_PARAMS = 2026;
const AUTH_RETRY_COUNT = 2;

interface SessionInfo {
    token: string;
    password: string;
    accessToken: string;
    sessionUid: string;
}

/**
 * usePublicSession maintain authentication of public session for shared links.
 * To properly authenticate, user should first init SRP handshake, followed by
 * unlocking session with password. Then any allowed request for this session
 * can be made. In case the access token expires, request will automatically
 * reauth with the same token and password and retry.
 */
function usePublicSessionProvider() {
    const api = useApi();
    const debouncedRequest = useDebouncedRequest();
    const [hasSession, setHasSession] = useState(false);
    const sessionInfo = useRef<SessionInfo>();
    const auth = useAuthentication();
    const [user, setUser] = useState<UserModel>();

    const initHandshake = async (token: string) => {
        /*
            initHandshake is the first request, which can fail, so we set the auth headers for the metrics.
            Metrics to be authenticated either needs a persisted session (default, as below) or an access token set in initSession().
            In case you neither have persisted session or access token, you will be 401 Unauthorized to call metrics.
        */
        const UID = getLastActivePersistedUserSessionUID();
        if (UID) {
            metrics.setAuthHeaders(UID);
        }

        const localID = getLastPersistedLocalID();
        if (localID !== null) {
            try {
                const resumedSession = await resumeSession({ api, localID });
                if (resumedSession.keyPassword) {
                    auth.setPassword(resumedSession.keyPassword);
                }
                setUser(formatUser(resumedSession.User));
            } catch (e) {
                // TODO: Probably getLastPersistedLocalID is the source of issue
                // Investigate why later
                console.warn('Cannot resume session');
            }
        }

        return api<SRPHandshakeInfo>(queryInitSRPHandshake(token)).then((handshakeInfo) => {
            return {
                handshakeInfo,
                isLegacySharedUrl: isLegacySharedUrl({ flags: handshakeInfo.Flags }),
                hasCustomPassword: hasCustomPassword({ flags: handshakeInfo.Flags }),
                hasGeneratedPasswordIncluded: hasGeneratedPasswordIncluded({ flags: handshakeInfo.Flags }),
            };
        });
    };

    const getSessionToken = async (
        token: string,
        password: string,
        initHandshake: SRPHandshakeInfo
    ): Promise<{ AccessToken: string; UID: string }> => {
        const { Modulus, ServerEphemeral, UrlPasswordSalt, SRPSession, Version } = initHandshake;

        /*
            If user is logged-in, re-use the current session UID
            This inform the backend of who is accessing the public session
        */
        const UID = getLastActivePersistedUserSessionUID();

        const response = await srpAuth({
            api,
            credentials: { password },
            info: {
                Modulus,
                ServerEphemeral,
                Version,
                Salt: UrlPasswordSalt,
                SRPSession,
            },
            config: {
                ...(UID && { headers: getUIDHeaders(UID) }),
                ...queryShareURLAuth(token),
            },
        });
        return response.json();
    };

    const initSession = async (token: string, password: string, handshakeInfo: SRPHandshakeInfo) => {
        return getSessionToken(token, password, handshakeInfo).then(({ AccessToken, UID }) => {
            setHasSession(true);
            sessionInfo.current = {
                token,
                password,
                accessToken: AccessToken,
                sessionUid: UID,
            };
            // This enables metrics to work for both auth and un-auth customers
            metrics.setAuthHeaders(UID, AccessToken);
            return sessionInfo.current;
        });
    };

    const queryWithHeaders = (query: any) => {
        if (!sessionInfo.current) {
            // This should not happend. If you see this, it indicate wrong flow.
            throw new Error('Cannot query unauthenticated session');
        }

        return withAuthHeaders(sessionInfo.current.sessionUid, sessionInfo.current.accessToken, query);
    };

    const shouldReauth = (error: any) => {
        const apiError = getApiError(error);
        return apiError.status === HTTP_ERROR_CODES.UNAUTHORIZED;
    };

    const reauth = async () => {
        if (!sessionInfo.current) {
            // This should not happend. If you see this, it indicate wrong flow.
            throw new Error('Cannot reauth unauthenticated session');
        }

        const { handshakeInfo } = await initHandshake(sessionInfo.current.token);
        await initSession(sessionInfo.current.token, sessionInfo.current.password, handshakeInfo).catch((err) => {
            // Custom password was changed probably, lets refresh and ask again.
            if (err?.data?.Code === ERROR_CODE_INVALID_SRP_PARAMS) {
                setHasSession(false);
            }
            throw err;
        });
    };

    const request = <T,>(args: any, abortSignal?: AbortSignal) => {
        const fn = () => debouncedRequest<T>(queryWithHeaders(args), abortSignal);

        return retryOnError<T>({
            fn,
            shouldRetryBasedOnError: shouldReauth,
            beforeRetryCallback: reauth,
            maxRetriesNumber: AUTH_RETRY_COUNT,
        })();
    };

    const getSessionInfo = () => sessionInfo.current;

    return {
        user,
        hasSession,
        initHandshake,
        initSession,
        request,
        getSessionInfo,
    };
}

const PublicSessionContext = createContext<ReturnType<typeof usePublicSessionProvider> | null>(null);

export function PublicSessionProvider({ children }: { children: React.ReactNode }) {
    const value = usePublicSessionProvider();
    return <PublicSessionContext.Provider value={value}>{children}</PublicSessionContext.Provider>;
}

export default function usePublicSession() {
    const state = useContext(PublicSessionContext);
    if (!state) {
        throw new Error('Trying to use uninitialized PublicSessionProvider');
    }
    return state;
}
